import{_ as e,o as t,c as r,ag as o}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"管理运行环境","description":"创建运行环境、关联节点并部署基础服务，核对真实就绪状态，谨慎处理重部署和删除。","frontmatter":{"title":"管理运行环境","description":"创建运行环境、关联节点并部署基础服务，核对真实就绪状态，谨慎处理重部署和删除。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/runtime-environments.md","filePath":"zh/使用指南/管理运行环境.md"}'),n={name:"zh/guide/runtime-environments.md"};function i(s,a,l,p,d,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="管理运行环境" tabindex="-1">管理运行环境 <a class="header-anchor" href="#管理运行环境" aria-label="Permalink to &quot;管理运行环境&quot;">​</a></h1><p>由组织管理员或运维人员操作：进入 <strong>“运维管理” → “运行概览”</strong>，核对当前环境。需要选择其他环境时使用“切换运行环境”。</p><p>本页不用于修改工程源码，也不把新建环境当成服务器和基础服务已经自动准备完毕。</p><h2 id="_1-查看或创建环境" tabindex="-1">1. 查看或创建环境 <a class="header-anchor" href="#_1-查看或创建环境" aria-label="Permalink to &quot;1. 查看或创建环境&quot;">​</a></h2><p>点击 **“管理运行环境”**查看环境列表。系统默认环境受到保护，不能像普通环境一样删除。</p><p>确需新增时：</p><ol><li>点击 <strong>“新建运行环境”</strong>。</li><li>填写能区分用途的“运行环境名称”。</li><li>点击 <strong>“创建环境”</strong>，等待成功。</li><li>打开该环境，核对名称、节点和初始化状态。</li></ol><p>已有合适环境时不必为每个工程重新创建一个环境。读取失败先重试，不把空列表当成环境丢失。</p><h2 id="_2-关联已接入节点" tabindex="-1">2. 关联已接入节点 <a class="header-anchor" href="#_2-关联已接入节点" aria-label="Permalink to &quot;2. 关联已接入节点&quot;">​</a></h2><p>在目标环境中使用 **“关联节点”**或初始化提示中的“关联物理节点”，选择获准且可用的节点，点击 <strong>“添加节点”</strong>。</p><p>先核对节点名称、地址、类型与状态。没有候选时，按<a href="/induframe-docs/zh/guide/runtime-nodes.html">节点管理</a>确认接入和资格，不随便关联用途不明的服务器。</p><p>关联成功只说明节点属于当前环境，还需准备基础服务、核对运行资格和容量。</p><h2 id="_3-准备基础服务" tabindex="-1">3. 准备基础服务 <a class="header-anchor" href="#_3-准备基础服务" aria-label="Permalink to &quot;3. 准备基础服务&quot;">​</a></h2><p>点击 <strong>“部署基础服务”</strong>，按页面为各项服务选择运行节点。关系库与时序库需要遵守界面的同节点要求，服务数据目录沿用节点安装时的安排，不在此手工编造路径。</p><p>核对服务分布后点击 <strong>“创建部署任务”</strong>，到概览、服务详情和运维记录等待结果。任务创建成功不等于服务已经健康。</p><p>当前基础服务界面开放的是单机部署方式，主备和集群选项标为“后续开放”。可以登记或分配多个节点，不等于已经获得数据库主备、集群或自动容灾保证。</p><h2 id="_4-检查能否承载工程" tabindex="-1">4. 检查能否承载工程 <a class="header-anchor" href="#_4-检查能否承载工程" aria-label="Permalink to &quot;4. 检查能否承载工程&quot;">​</a></h2><p>检查环境节点、基础服务、磁盘容量和有效观测。存在异常或指标过期时，先查看具体原因；环境未就绪时不要继续提交工程部署。</p><p>需要通过环境统一地址访问工程时，在运行概览的 **“访问入口”**按交付安排配置并启用，部署时再选择“环境入口”。地址、网络和证书应由维护人员确认。</p><h2 id="_5-重部署和删除不是普通刷新" tabindex="-1">5. 重部署和删除不是普通刷新 <a class="header-anchor" href="#_5-重部署和删除不是普通刷新" aria-label="Permalink to &quot;5. 重部署和删除不是普通刷新&quot;">​</a></h2><p><strong>基础服务重新部署可能删除重建服务并清空其中的数据。</strong> 不为刷新状态直接使用；先确认备份、业务停机和已有工程部署，按界面要求处理依赖。</p><p>删除普通运行环境会清理该环境的工程运行资源、基础服务、隔离空间和持久化数据，中心运行集群和物理节点本身不会因此被卸载。</p><p>确需删除时，核对环境名称及影响，按要求输入名称并创建删除任务，等待记录中的真实结果。不要把删除任务已创建当成数据已安全备份或清理已完成。</p><p>下一步：<a href="/induframe-docs/zh/guide/deployments.html">创建工程部署</a> · <a href="/induframe-docs/zh/guide/operations-records.html">查看运维记录</a>。</p>',24)])])}const u=e(n,[["render",i]]);export{c as __pageData,u as default};
